INSERT INTO curated_plant_content_third(product_code,expected_name,latin,short_text,full_text,care_text,light,watering,guide_light,guide_water) VALUES
  (45,'Асплениум Парвати','Asplenium','Розеточный папоротник с длинными зелёными вайями.','Асплениум образует плотную розетку из цельных или волнистых вай. У формы «Криспи Вейв» край листа выраженно волнистый; точный вид «Парвати» по одному торговому названию не устанавливаем.','Поставьте в яркий рассеянный свет, вдали от прямого солнца. Поддерживайте субстрат умеренно влажным, поливая по краю горшка и не заливая центр розетки. Не держите у батареи.','diffused','moderate','Поставьте в яркий рассеянный свет, вдали от прямого солнца.','Поддерживайте субстрат умеренно влажным, поливая по краю горшка и не заливая центр розетки.'),
  (43,'Асплениум нидус «Криспи Вейв»','Asplenium','Розеточный папоротник с длинными зелёными вайями.','Асплениум образует плотную розетку из цельных или волнистых вай. У формы «Криспи Вейв» край листа выраженно волнистый; точный вид «Парвати» по одному торговому названию не устанавливаем.','Поставьте в яркий рассеянный свет, вдали от прямого солнца. Поддерживайте субстрат умеренно влажным, поливая по краю горшка и не заливая центр розетки. Не держите у батареи.','diffused','moderate','Поставьте в яркий рассеянный свет, вдали от прямого солнца.','Поддерживайте субстрат умеренно влажным, поливая по краю горшка и не заливая центр розетки.'),
  (46,'Бамбук Лаки Драцена Сандериана','Dracaena sanderiana','Драцена Сандера с тонкими побегами, известная как «лаки бамбук».','Несмотря на торговое имя, лаки бамбук относится к драценам, а не к настоящему бамбуку. Прямые и изогнутые побеги — формы выращивания одного вида Dracaena sanderiana.','Держите в ярком рассеянном свете без прямого полуденного солнца. При выращивании в грунте поливайте после лёгкого подсыхания поверхности; вода должна свободно уходить из горшка. Берегите от холода.','diffused','moderate','Держите в ярком рассеянном свете без прямого полуденного солнца.','При выращивании в грунте поливайте после лёгкого подсыхания поверхности; вода должна свободно уходить из горшка.'),
  (47,'Бамбук Лаки Драцена Сандериана прямой','Dracaena sanderiana','Драцена Сандера с тонкими побегами, известная как «лаки бамбук».','Несмотря на торговое имя, лаки бамбук относится к драценам, а не к настоящему бамбуку. Прямые и изогнутые побеги — формы выращивания одного вида Dracaena sanderiana.','Держите в ярком рассеянном свете без прямого полуденного солнца. При выращивании в грунте поливайте после лёгкого подсыхания поверхности; вода должна свободно уходить из горшка. Берегите от холода.','diffused','moderate','Держите в ярком рассеянном свете без прямого полуденного солнца.','При выращивании в грунте поливайте после лёгкого подсыхания поверхности; вода должна свободно уходить из горшка.'),
  (104,'Драцена Сандера','Dracaena sanderiana','Драцена Сандера с тонкими побегами, известная как «лаки бамбук».','Несмотря на торговое имя, лаки бамбук относится к драценам, а не к настоящему бамбуку. Прямые и изогнутые побеги — формы выращивания одного вида Dracaena sanderiana.','Держите в ярком рассеянном свете без прямого полуденного солнца. При выращивании в грунте поливайте после лёгкого подсыхания поверхности; вода должна свободно уходить из горшка. Берегите от холода.','diffused','moderate','Держите в ярком рассеянном свете без прямого полуденного солнца.','При выращивании в грунте поливайте после лёгкого подсыхания поверхности; вода должна свободно уходить из горшка.'),
  (130,'Лавр благородный','Laurus nobilis','Лавр благородный — вечнозелёное растение с ароматными листьями.','Лавр благородный выращивают в контейнере как куст или небольшое дерево. Плотные кожистые листья сохраняются круглый год, а форму кроны можно поддерживать обрезкой.','Поставьте в солнечное место или лёгкую полутень. Поливайте после подсыхания верхнего слоя в хорошо дренированном грунте; не оставляйте корни в воде. Зимой защищайте контейнер от сильного промерзания.','sunny','moderate','Поставьте в солнечное место или лёгкую полутень.','Поливайте после подсыхания верхнего слоя в хорошо дренированном грунте; не оставляйте корни в воде.'),
  (131,'Лавр куст','Laurus nobilis','Лавр благородный — вечнозелёное растение с ароматными листьями.','Лавр благородный выращивают в контейнере как куст или небольшое дерево. Плотные кожистые листья сохраняются круглый год, а форму кроны можно поддерживать обрезкой.','Поставьте в солнечное место или лёгкую полутень. Поливайте после подсыхания верхнего слоя в хорошо дренированном грунте; не оставляйте корни в воде. Зимой защищайте контейнер от сильного промерзания.','sunny','moderate','Поставьте в солнечное место или лёгкую полутень.','Поливайте после подсыхания верхнего слоя в хорошо дренированном грунте; не оставляйте корни в воде.'),
  (148,'Монстера Monkey Leaf','Monstera adansonii','Монстера Monkey Leaf с ажурными отверстиями в листьях.','Monstera adansonii — тропическая лиана с сердцевидными листьями и овальными отверстиями между жилками. Побеги можно направить по опоре или оставить свисать.','Выберите яркий непрямой свет и тепло. В период роста поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой полив сокращайте.','diffused','moderate','Выберите яркий непрямой свет и тепло.','В период роста поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой полив сокращайте.'),
  (152,'Монстера Тайское созвездие','Monstera deliciosa ''Thai Constellation''','Пестролистная монстера Thai Constellation с кремовыми пятнами на листьях.','Monstera deliciosa Thai Constellation — вьющаяся пестролистная форма. По мере взросления листья становятся крупнее и образуют характерные разрезы и отверстия; для роста побегам нужна опора.','Держите в ярком непрямом свете: белые участки листа легче обгорают под прямым солнцем. Поливайте после подсыхания верхнего слоя грунта и сливайте воду из поддона; обеспечьте рыхлый субстрат.','diffused','moderate','Держите в ярком непрямом свете: белые участки листа легче обгорают под прямым солнцем.','Поливайте после подсыхания верхнего слоя грунта и сливайте воду из поддона; обеспечьте рыхлый субстрат.'),
  (165,'Пахира Акватика плетеная','Pachira aquatica','Пахира акватика с пальчатыми листьями и плетёным стволом.','Пахира акватика — тропическое дерево, которое в комнатной культуре часто выращивают из нескольких переплетённых стволиков. Её крупные листья состоят из нескольких листочков.','Поставьте в яркий рассеянный свет. Поливайте после подсыхания верхнего слоя грунта и сливайте воду из поддона; зимой уменьшайте полив. Не допускайте холодных сквозняков.','diffused','moderate','Поставьте в яркий рассеянный свет.','Поливайте после подсыхания верхнего слоя грунта и сливайте воду из поддона; зимой уменьшайте полив.'),
  (179,'Сингониум','Syngonium','Сингониум с листьями стреловидной формы и гибкими побегами.','Сингониум — тропическое растение семейства ароидных. Молодые листья обычно стреловидные; с возрастом растение может образовывать более длинные побеги, которым дают опору или позволяют свисать.','Держите в ярком рассеянном свете без жёсткого солнца. Поливайте после подсыхания поверхности рыхлого субстрата, затем сливайте лишнюю воду; берегите от холода.','diffused','moderate','Держите в ярком рассеянном свете без жёсткого солнца.','Поливайте после подсыхания поверхности рыхлого субстрата, затем сливайте лишнюю воду; берегите от холода.'),
  (186,'Стрелиция Николая','Strelitzia nicolai','Стрелиция Николая с крупными листьями для просторного светлого места.','Strelitzia nicolai образует высокие черешки и крупные похожие на банановые листья. В зрелом возрасте становится значительно больше компактных комнатных растений, поэтому ей нужно место для роста.','Поставьте в очень светлое место и постепенно приучайте к прямому солнцу. В период роста поливайте регулярно после подсыхания верхнего слоя, зимой реже; не допускайте застоя воды.','sunny','moderate','Поставьте в очень светлое место и постепенно приучайте к прямому солнцу.','В период роста поливайте регулярно после подсыхания верхнего слоя, зимой реже; не допускайте застоя воды.'),
  (204,'Фикус Голден Кинг','Ficus benjamina','Фикус Бенджамина с многочисленными небольшими листьями и разветвлённой кроной.','Фикус Бенджамина формирует густую крону из тонких ветвей и небольших листьев. Цвет и рисунок листвы зависят от сорта; растение лучше чувствует себя на постоянном светлом месте.','Обеспечьте яркий рассеянный свет, особенно пёстрым формам. Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне. Берегите от холодных сквозняков и резкой смены условий: из-за стресса возможен листопад.','diffused','moderate','Обеспечьте яркий рассеянный свет, особенно пёстрым формам.','Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне.'),
  (210,'Фикус Наташа','Ficus benjamina','Фикус Бенджамина с многочисленными небольшими листьями и разветвлённой кроной.','Фикус Бенджамина формирует густую крону из тонких ветвей и небольших листьев. Цвет и рисунок листвы зависят от сорта; растение лучше чувствует себя на постоянном светлом месте.','Обеспечьте яркий рассеянный свет, особенно пёстрым формам. Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне. Берегите от холодных сквозняков и резкой смены условий: из-за стресса возможен листопад.','diffused','moderate','Обеспечьте яркий рассеянный свет, особенно пёстрым формам.','Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне.'),
  (213,'Фикус Твилайт','Ficus benjamina','Фикус Бенджамина с многочисленными небольшими листьями и разветвлённой кроной.','Фикус Бенджамина формирует густую крону из тонких ветвей и небольших листьев. Цвет и рисунок листвы зависят от сорта; растение лучше чувствует себя на постоянном светлом месте.','Обеспечьте яркий рассеянный свет, особенно пёстрым формам. Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне. Берегите от холодных сквозняков и резкой смены условий: из-за стресса возможен листопад.','diffused','moderate','Обеспечьте яркий рассеянный свет, особенно пёстрым формам.','Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне.'),
  (212,'Фикус Руби','Ficus elastica','Фикус эластика с крупными плотными кожистыми листьями.','Фикус эластика создаёт выразительный зелёный вертикальный акцент. Его крупные листья лучше выглядят при достаточном освещении и регулярном удалении пыли.','Держите в ярком рассеянном свете; пёстрым формам особенно важен свет. Поливайте после подсыхания верхнего слоя грунта и не оставляйте воду в поддоне. Избегайте резкой смены места и холодных сквозняков.','diffused','moderate','Держите в ярком рассеянном свете; пёстрым формам особенно важен свет.','Поливайте после подсыхания верхнего слоя грунта и не оставляйте воду в поддоне.'),
  (214,'Фикус Шривериана','Ficus elastica ''Schrijveriana''','Фикус Шривериана с крупными мраморными листьями.','Ficus elastica Schrijveriana — пестролистная форма каучуконосного фикуса. На плотных листьях сочетаются зелёные, серые и кремовые участки; выраженность рисунка зависит от освещения.','Поставьте в яркий рассеянный свет, защищая листья от резкого полуденного солнца. Поливайте после подсыхания верхнего слоя грунта, сливайте воду из поддона; берегите от холодных сквозняков.','diffused','moderate','Поставьте в яркий рассеянный свет, защищая листья от резкого полуденного солнца.','Поливайте после подсыхания верхнего слоя грунта, сливайте воду из поддона; берегите от холодных сквозняков.'),
  (228,'Фиттония','Fittonia','Невысокая фиттония с выразительной сеткой жилок на листьях.','Фиттония — компактное тропическое растение, которое выращивают ради контрастных жилок на небольших листьях. Ей подходят тёплые места с влажным воздухом без палящего солнца.','Дайте рассеянный свет или лёгкую полутень. Сохраняйте грунт слегка влажным, но не мокрым: при пересушке листья быстро теряют упругость. Не ставьте у отопления.','diffused','frequent','Дайте рассеянный свет или лёгкую полутень.','Сохраняйте грунт слегка влажным, но не мокрым: при пересушке листья быстро теряют упругость.'),
  (229,'Хамедорея Элеганс','Chamaedorea elegans','Хамедорея элеганс — компактная пальма с тонкими перистыми листьями.','Хамедорея элеганс медленно растёт и образует изящные дугообразные вайи. Эта пальма подходит для выращивания в комнате без прямого обжигающего солнца.','Поставьте в рассеянный свет или лёгкую полутень. Поливайте после подсыхания поверхности грунта и не оставляйте воду в поддоне. Берегите от горячего сухого воздуха.','diffused','moderate','Поставьте в рассеянный свет или лёгкую полутень.','Поливайте после подсыхания поверхности грунта и не оставляйте воду в поддоне.'),
  (230,'Хедера','Hedera','Комнатный плющ с длинными побегами для подвесного кашпо или опоры.','Хедера — вечнозелёная лиана с побегами, которые могут свисать или оплетать опору. Форма и рисунок листьев зависят от сорта; точный вид карточки не установлен.','Выберите непрямой свет; зелёные формы переносят и более тенистое место. Поливайте после подсыхания поверхности грунта, не допуская застоя воды. Держите подальше от горячей батареи.','diffused','moderate','Выберите непрямой свет; зелёные формы переносят и более тенистое место.','Поливайте после подсыхания поверхности грунта, не допуская застоя воды.'),
  (234,'Хойя','Hoya','Хойя — вьющийся комнатный цветок с плотными листьями.','Хойи образуют длинные побеги и со временем могут цвести гроздьями восковых цветков. Вид и рисунок листьев в этой карточке не подтверждены, поэтому особенности сорта не обещаем.','Дайте яркий непрямой свет и тепло. Поливайте умеренно после подсыхания части субстрата; избыток воды сливайте. Для длинных побегов предусмотрите опору или подвесное размещение.','diffused','moderate','Дайте яркий непрямой свет и тепло.','Поливайте умеренно после подсыхания части субстрата; избыток воды сливайте.'),
  (241,'Шеффлера','Schefflera','Шеффлера с лучистыми пальчатыми листьями и стройной кроной.','Шеффлера — вечнозелёное декоративнолистное растение: несколько листочков расходятся от общего черешка как спицы зонтика. По торговым названиям «Герда» и «Луизиана» ботанический вид не уточняем.','Поставьте в яркий рассеянный свет, защищая от палящего солнца. Поливайте после подсыхания верхнего слоя и сливайте лишнюю воду; зимой поливайте осторожнее.','diffused','moderate','Поставьте в яркий рассеянный свет, защищая от палящего солнца.','Поливайте после подсыхания верхнего слоя и сливайте лишнюю воду; зимой поливайте осторожнее.'),
  (242,'Шеффлера (Герда)','Schefflera','Шеффлера с лучистыми пальчатыми листьями и стройной кроной.','Шеффлера — вечнозелёное декоративнолистное растение: несколько листочков расходятся от общего черешка как спицы зонтика. По торговым названиям «Герда» и «Луизиана» ботанический вид не уточняем.','Поставьте в яркий рассеянный свет, защищая от палящего солнца. Поливайте после подсыхания верхнего слоя и сливайте лишнюю воду; зимой поливайте осторожнее.','diffused','moderate','Поставьте в яркий рассеянный свет, защищая от палящего солнца.','Поливайте после подсыхания верхнего слоя и сливайте лишнюю воду; зимой поливайте осторожнее.'),
  (243,'Шеффлера Луизиана','Schefflera','Шеффлера с лучистыми пальчатыми листьями и стройной кроной.','Шеффлера — вечнозелёное декоративнолистное растение: несколько листочков расходятся от общего черешка как спицы зонтика. По торговым названиям «Герда» и «Луизиана» ботанический вид не уточняем.','Поставьте в яркий рассеянный свет, защищая от палящего солнца. Поливайте после подсыхания верхнего слоя и сливайте лишнюю воду; зимой поливайте осторожнее.','diffused','moderate','Поставьте в яркий рассеянный свет, защищая от палящего солнца.','Поливайте после подсыхания верхнего слоя и сливайте лишнюю воду; зимой поливайте осторожнее.'),
  (244,'Эпипремнум','Epipremnum','Эпипремнум — гибкая лиана для опоры или подвесного кашпо.','Эпипремнум образует длинные побеги с глянцевыми сердцевидными листьями. Его можно выращивать свисающим с полки или направлять вверх по опоре; точный сорт этой карточки не установлен.','Дайте яркий рассеянный свет, избегая сильного прямого солнца. Поливайте, когда верхние сантиметры субстрата подсохнут, и не держите корни в воде.','diffused','moderate','Дайте яркий рассеянный свет, избегая сильного прямого солнца.','Поливайте, когда верхние сантиметры субстрата подсохнут, и не держите корни в воде.'),
  (123,'Кофе Арабика','Coffea arabica','Кофе арабика с глянцевыми тёмно-зелёными листьями.','Coffea arabica — вечнозелёный кустарник или небольшое дерево. При хорошем уходе взрослое растение может цвести белыми ароматными цветками, но цветение молодого экземпляра не гарантировано.','Поставьте в светлое место без палящего солнца. Держите почву умеренно влажной, поливая после начала подсыхания поверхности; сливайте лишнюю воду и избегайте холодных сквозняков.','diffused','moderate','Поставьте в светлое место без палящего солнца.','Держите почву умеренно влажной, поливая после начала подсыхания поверхности; сливайте лишнюю воду и избегайте холодных сквозняков.'),
  (32,'Ананас Корона','Ananas comosus','Ананас — розеточное растение с жёсткими листьями и декоративным плодом.','Ананас относится к наземным бромелиевым. Плотная розетка длинных листьев окружает цветонос; при подходящих условиях после цветения формируется плод.','Держите в очень светлом тёплом месте. Во время активного роста поливайте после подсыхания верхнего слоя хорошо дренированного субстрата; в прохладный сезон сократите полив.','sunny','moderate','Держите в очень светлом тёплом месте.','Во время активного роста поливайте после подсыхания верхнего слоя хорошо дренированного субстрата; в прохладный сезон сократите полив.'),
  (238,'Цикас (саговник)','Cycas','Цикас с жёсткими перистыми листьями, похожий на небольшую пальму.','Цикас — медленно растущее саговниковое растение, не настоящая пальма. Листья располагаются розеткой вокруг короткого ствола; растение ядовито при поедании. Вид по названию не уточняем.','Поставьте в яркий свет с защитой от самого жаркого полуденного солнца. Поливайте умеренно во время роста, после подсыхания верхнего слоя; зимой значительно реже.','sunny','moderate','Поставьте в яркий свет с защитой от самого жаркого полуденного солнца.','Поливайте умеренно во время роста, после подсыхания верхнего слоя; зимой значительно реже.'),
  (77,'Бонсай Портулакария Афра','Portulacaria afra','Бонсай из портулакарии с мелкими мясистыми листьями.','Portulacaria afra — суккулентный кустарник с красноватыми молодыми побегами и округлыми листьями. В форме бонсай крону поддерживают аккуратной обрезкой.','Поставьте в максимально светлое место. Поливайте только после просыхания субстрата, обязательно используйте горшок с дренажным отверстием. Зимой при замедлении роста поливайте редко.','sunny','rare','Поставьте в максимально светлое место.','Поливайте только после просыхания субстрата, обязательно используйте горшок с дренажным отверстием.'),
  (153,'Муса (Банан)','Musa','Банановое растение с крупными тропическими листьями.','Муса — травянистое растение: видимый «ствол» образован основаниями листьев. Плодоношение комнатного экземпляра не обещаем; его ценят прежде всего за крупную листву.','Поставьте в тёплое очень светлое место. В период активного роста поливайте регулярно, поддерживая грунт влажным без застоя воды; зимой сократите полив и берегите от холода.','sunny','frequent','Поставьте в тёплое очень светлое место.','В период активного роста поливайте регулярно, поддерживая грунт влажным без застоя воды; зимой сократите полив и берегите от холода.'),
  (120,'Калла','Zantedeschia','Калла с крупными листьями и выразительным покрывалом соцветия.','Каллы относятся к роду Zantedeschia. Настоящие мелкие цветки собраны в початок внутри окрашенного покрывала; точный вид и окраска этого экземпляра в названии не указаны.','Во время роста поставьте в светлое место без палящего солнца. Держите грунт умеренно влажным. После завершения сезона роста полив уменьшайте; период покоя для комнатной каллы важен.','diffused','frequent','Во время роста поставьте в светлое место без палящего солнца.','Держите грунт умеренно влажным.'),
  (124,'Крассула','Crassula','Крассула — суккулент с мясистыми листьями и ветвящимися побегами.','Крассулы запасают влагу в листьях и лучше переносят краткую сухость, чем постоянно мокрый грунт. Точный вид в названии этой карточки не указан.','Поставьте в очень светлое место. Посадите в хорошо дренированный субстрат и поливайте после полного просыхания значительной части грунта; зимой ещё реже.','sunny','rare','Поставьте в очень светлое место.','Посадите в хорошо дренированный субстрат и поливайте после полного просыхания значительной части грунта; зимой ещё реже.'),
  (125,'Крестовник Роули (Сенецио)','Curio rowleyanus','Крестовник Роули с тонкими свисающими побегами и листьями-шариками.','Растение, известное как Senecio rowleyanus, сейчас относят к роду Curio. Шаровидные мясистые листья нанизаны на длинные побеги, поэтому ему подходит подвесное размещение.','Дайте яркое место с несколькими часами мягкого солнца. Поливайте только после просыхания рыхлого субстрата; зимой поливайте очень редко и не держите корни в воде.','sunny','rare','Дайте яркое место с несколькими часами мягкого солнца.','Поливайте только после просыхания рыхлого субстрата; зимой поливайте очень редко и не держите корни в воде.'),
  (142,'Мимоза стыдливая','Mimosa pudica','Мимоза стыдливая складывает перистые листья при прикосновении.','Mimosa pudica — недолговечное тропическое растение с тонко рассечёнными листьями. Листочки реагируют на прикосновение, а летом могут появляться небольшие розовые соцветия.','Поставьте в очень светлое тёплое место. Поливайте после начала подсыхания поверхности субстрата, не допуская застоя воды; защищайте от холода.','sunny','moderate','Поставьте в очень светлое тёплое место.','Поливайте после начала подсыхания поверхности субстрата, не допуская застоя воды; защищайте от холода.'),
  (145,'Мирт','Myrtus communis','Мирт обыкновенный с мелкими ароматными вечнозелёными листьями.','Myrtus communis формирует плотный вечнозелёный кустарник. Штамбовая и спиральная формы получены формировкой кроны, а не другим видом растения.','Выберите солнечное место с хорошим проветриванием. Поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой держите светло и прохладнее, поливая реже.','sunny','moderate','Выберите солнечное место с хорошим проветриванием.','Поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой держите светло и прохладнее, поливая реже.'),
  (146,'Мирт на штамбе','Myrtus communis','Мирт обыкновенный с мелкими ароматными вечнозелёными листьями.','Myrtus communis формирует плотный вечнозелёный кустарник. Штамбовая и спиральная формы получены формировкой кроны, а не другим видом растения.','Выберите солнечное место с хорошим проветриванием. Поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой держите светло и прохладнее, поливая реже.','sunny','moderate','Выберите солнечное место с хорошим проветриванием.','Поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой держите светло и прохладнее, поливая реже.'),
  (147,'Мирт спиральный','Myrtus communis','Мирт обыкновенный с мелкими ароматными вечнозелёными листьями.','Myrtus communis формирует плотный вечнозелёный кустарник. Штамбовая и спиральная формы получены формировкой кроны, а не другим видом растения.','Выберите солнечное место с хорошим проветриванием. Поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой держите светло и прохладнее, поливая реже.','sunny','moderate','Выберите солнечное место с хорошим проветриванием.','Поливайте после лёгкого подсыхания верхнего слоя, не оставляя воду в поддоне; зимой держите светло и прохладнее, поливая реже.'),
  (67,'Бонсай Метасеквойя','Metasequoia glyptostroboides','Бонсай из метасеквойи — листопадного хвойного дерева.','Метасеквойя глиптостробовидная отличается мягкой зелёной хвоей, которая осенью буреет и опадает. Форма «лес» объединяет несколько растений того же вида; зимний листопад естественен.','Поставьте на открытом воздухе в светлое место, защищая маленький горшок от сильного промерзания. В сезон роста поддерживайте субстрат равномерно влажным; зимой поливайте по состоянию, не оставляя корни сухими надолго.','sunny','frequent','Поставьте на открытом воздухе в светлое место, защищая маленький горшок от сильного промерзания.','В сезон роста поддерживайте субстрат равномерно влажным; зимой поливайте по состоянию, не оставляя корни сухими надолго.'),
  (68,'Бонсай Метасеквойя Лес','Metasequoia glyptostroboides','Бонсай из метасеквойи — листопадного хвойного дерева.','Метасеквойя глиптостробовидная отличается мягкой зелёной хвоей, которая осенью буреет и опадает. Форма «лес» объединяет несколько растений того же вида; зимний листопад естественен.','Поставьте на открытом воздухе в светлое место, защищая маленький горшок от сильного промерзания. В сезон роста поддерживайте субстрат равномерно влажным; зимой поливайте по состоянию, не оставляя корни сухими надолго.','sunny','frequent','Поставьте на открытом воздухе в светлое место, защищая маленький горшок от сильного промерзания.','В сезон роста поддерживайте субстрат равномерно влажным; зимой поливайте по состоянию, не оставляя корни сухими надолго.'),
  (88,'Гибискус','Hibiscus','Гибискус с крупными цветками и глянцевой листвой.','Комнатные гибискусы выращивают ради ярких крупных цветков. Вид и окраска конкретного экземпляра в названии не указаны, поэтому сортовые признаки не заявляем.','Поставьте в очень светлое тёплое место. Во время активного роста поливайте после лёгкого подсыхания поверхности грунта и не допускайте длительной засухи; зимой полив сократите.','sunny','moderate','Поставьте в очень светлое тёплое место.','Во время активного роста поливайте после лёгкого подсыхания поверхности грунта и не допускайте длительной засухи; зимой полив сократите.'),
  (89,'Даваллия','Davallia','Даваллия — папоротник с тонкими вайями и ползучими пушистыми корневищами.','У даваллии корневища могут выходить на поверхность и свисать через край горшка. Это естественная особенность эпифитного папоротника; точный вид по карточке не устанавливаем.','Поставьте в яркий рассеянный свет. Поддерживайте влажность воздуха. Поливайте так, чтобы субстрат оставался умеренно влажным, но вода не стояла у корней; не засыпайте выступающие корневища.','diffused','frequent','Поставьте в яркий рассеянный свет.','Поливайте так, чтобы субстрат оставался умеренно влажным, но вода не стояла у корней; не засыпайте выступающие корневища.'),
  (167,'Платицериум','Platycerium','Платицериум — эпифитный папоротник с вайями, похожими на оленьи рога.','Платицериум образует разные типы вай: округлые прикрывают основание, а более длинные ветвятся. Вид данного экземпляра в карточке не уточнён.','Выберите яркий непрямой свет. Поддерживайте влажность воздуха. Поливайте умеренно, давая рыхлому субстрату слегка подсохнуть между поливами; не держите растение в стоячей воде.','diffused','moderate','Выберите яркий непрямой свет.','Поливайте умеренно, давая рыхлому субстрату слегка подсохнуть между поливами; не держите растение в стоячей воде.'),
  (170,'Рипсалис','Rhipsalis','Рипсалис — свисающий лесной кактус с тонкими ветвящимися побегами.','Рипсалисы в природе растут как эпифиты. В отличие от пустынных кактусов им подходит рассеянный свет и несколько более регулярный полив; точный вид этой карточки не установлен.','Поставьте в яркий рассеянный свет без жёсткого полуденного солнца. Поливайте после лёгкого подсыхания субстрата, в зимний период реже; обеспечьте свободный сток воды.','diffused','moderate','Поставьте в яркий рассеянный свет без жёсткого полуденного солнца.','Поливайте после лёгкого подсыхания субстрата, в зимний период реже; обеспечьте свободный сток воды.'),
  (139,'Маранта','Maranta','Маранта с узорчатыми листьями, которые меняют положение к вечеру.','Маранта — невысокое тропическое растение с выразительным рисунком листьев. Листовые пластинки могут приподниматься к вечеру; вид конкретного экземпляра не указан.','Поставьте в яркий рассеянный свет или лёгкую полутень. Держите субстрат слегка влажным, поливая после начала подсыхания поверхности; берегите от сухого горячего воздуха.','diffused','frequent','Поставьте в яркий рассеянный свет или лёгкую полутень.','Держите субстрат слегка влажным, поливая после начала подсыхания поверхности; берегите от сухого горячего воздуха.'),
  (180,'Синнингия Глоксиния Соната','Sinningia','Глоксиния Соната — компактная синнингия с крупными цветками.','Под торговым названием «глоксиния» обычно выращивают синнингию. Это клубневое растение с бархатистыми листьями и крупными колокольчатыми цветками; окраску серии Sonata без этикетки не уточняем.','Во время роста поставьте в яркий рассеянный свет. Поливайте по краю горшка после лёгкого подсыхания поверхности, не заливая листья и клубень; после отмирания надземной части полив сократите.','diffused','moderate','Во время роста поставьте в яркий рассеянный свет.','Поливайте по краю горшка после лёгкого подсыхания поверхности, не заливая листья и клубень; после отмирания надземной части полив сократите.'),
  (116,'Каладиум','Caladium','Каладиум с тонкими листьями стреловидной формы и ярким рисунком.','Каладиумы растут из клубней и образуют декоративные листья. Точный сорт этой карточки не установлен; в конце сезона листья могут отмирать перед периодом покоя.','Поставьте в яркий рассеянный свет и тепло. Во время роста поддерживайте грунт умеренно влажным без застоя воды; при переходе к покою постепенно сократите полив.','diffused','moderate','Поставьте в яркий рассеянный свет и тепло.','Во время роста поддерживайте грунт умеренно влажным без застоя воды; при переходе к покою постепенно сократите полив.'),
  (121,'Клузия','Clusia','Клузия с плотными глянцевыми листьями и прочными побегами.','Клузии — тропические вечнозелёные кустарники с кожистой листвой. У этой карточки не указан точный вид; комнатное растение ценят за компактную крону, а цветение не гарантируем.','Поставьте в яркий фильтрованный свет без жаркого полуденного солнца. Летом поливайте после лёгкого подсыхания поверхности, зимой осторожнее; не оставляйте воду в поддоне.','diffused','moderate','Поставьте в яркий фильтрованный свет без жаркого полуденного солнца.','Летом поливайте после лёгкого подсыхания поверхности, зимой осторожнее; не оставляйте воду в поддоне.'),
  (122,'Кордилина','Cordyline','Кордилина с длинными ремневидными листьями и стройным силуэтом.','Кордилины выращивают ради пучков узких листьев: окраска и будущая высота зависят от вида и сорта. У данной карточки вид не указан, поэтому размер взрослого растения не обещаем.','Выберите яркий рассеянный свет; пёстрые листья защищайте от жёсткого полуденного солнца. Поливайте после подсыхания верхнего слоя хорошо дренированного грунта и берегите от мороза.','diffused','moderate','Выберите яркий рассеянный свет; пёстрые листья защищайте от жёсткого полуденного солнца.','Поливайте после подсыхания верхнего слоя хорошо дренированного грунта и берегите от мороза.'),
  (240,'Циртомиум','Cyrtomium','Циртомиум — папоротник с плотными блестящими листочками на вайях.','Циртомиумы образуют изящные перистые вайи с кожистыми сегментами. Вид этой карточки не уточнён; в комнате растение держат вдали от сухого горячего воздуха.','Поставьте в рассеянный свет или лёгкую полутень. Поливайте после начала подсыхания поверхности, сохраняя субстрат умеренно влажным и не оставляя воду у корней.','diffused','moderate','Поставьте в рассеянный свет или лёгкую полутень.','Поливайте после начала подсыхания поверхности, сохраняя субстрат умеренно влажным и не оставляя воду у корней.'),
  (172,'Роза Кордана','Rosa','Компактная горшечная роза для светлого балкона или патио.','Миниатюрные и патио-розы подходят для контейнеров, но нуждаются в солнечном месте и сезонном уходе. Цвет и точный сорт конкретной карточки не установлены.','Поставьте на открытом воздухе в место с несколькими часами прямого солнца. Поливайте регулярно, когда верхний слой грунта подсыхает, не пересушивая весь ком; зимой защищайте контейнер от сильного промерзания.','sunny','frequent','Поставьте на открытом воздухе в место с несколькими часами прямого солнца.','Поливайте регулярно, когда верхний слой грунта подсыхает, не пересушивая весь ком; зимой защищайте контейнер от сильного промерзания.'),
  (173,'Роза Патио','Rosa','Компактная горшечная роза для светлого балкона или патио.','Миниатюрные и патио-розы подходят для контейнеров, но нуждаются в солнечном месте и сезонном уходе. Цвет и точный сорт конкретной карточки не установлены.','Поставьте на открытом воздухе в место с несколькими часами прямого солнца. Поливайте регулярно, когда верхний слой грунта подсыхает, не пересушивая весь ком; зимой защищайте контейнер от сильного промерзания.','sunny','frequent','Поставьте на открытом воздухе в место с несколькими часами прямого солнца.','Поливайте регулярно, когда верхний слой грунта подсыхает, не пересушивая весь ком; зимой защищайте контейнер от сильного промерзания.'),
  (190,'Традесканция','Tradescantia','Традесканция с гибкими побегами и декоративной листвой.','Традесканции — травянистые растения, которые выращивают ради формы и окраски листьев. Вид этой карточки не указан; побеги можно направить вдоль полки или выращивать в подвесном кашпо.','Дайте яркий рассеянный свет для сохранения окраски. Поливайте после подсыхания верхнего слоя грунта и сливайте избыток воды; зимой частоту полива уменьшайте.','diffused','moderate','Дайте яркий рассеянный свет для сохранения окраски.','Поливайте после подсыхания верхнего слоя грунта и сливайте избыток воды; зимой частоту полива уменьшайте.'),
  (58,'Бонсай Зелкова','Zelkova','Листопадный бонсай из зельквы с мелкой зубчатой листвой.','Зельквы — деревья с зубчатыми листьями и выразительной осенней окраской. Вид этого бонсай не указан; сезонный листопад для зельквы естественен.','Держите на открытом воздухе в солнечном месте или лёгкой полутени. В сезон роста проверяйте маленький горшок ежедневно и поливайте после подсыхания поверхности; зимой защищайте корневой ком от сильного промерзания.','sunny','frequent','Держите на открытом воздухе в солнечном месте или лёгкой полутени.','В сезон роста проверяйте маленький горшок ежедневно и поливайте после подсыхания поверхности; зимой защищайте корневой ком от сильного промерзания.'),
  (60,'Бонсай Кармона','Carmona','Кармона — комнатный бонсай с мелкими глянцевыми листьями.','Кармону выращивают как субтропический бонсай благодаря компактной листве и плотной кроне. При благоприятных условиях могут появляться мелкие белые цветки; цветение не гарантируем.','Поставьте в очень светлое тёплое место без холодных сквозняков. Поливайте после лёгкого подсыхания поверхности дренированного грунта, не позволяя маленькому кому полностью пересохнуть.','sunny','frequent','Поставьте в очень светлое тёплое место без холодных сквозняков.','Поливайте после лёгкого подсыхания поверхности дренированного грунта, не позволяя маленькому кому полностью пересохнуть.'),
  (65,'Бонсай Лигуструм (Бирючина китайская)','Ligustrum sinense','Бонсай из китайской бирючины с мелкой зелёной листвой.','Ligustrum sinense — китайская бирючина, которую можно формировать обрезкой. В зависимости от условий она бывает полувечнозелёной и способна частично сбрасывать листья.','Поставьте на открытом воздухе на солнце или в лёгкую полутень. В сезон роста поливайте после подсыхания поверхности грунта, не пересушивая маленький горшок; зимой защищайте корни от сильного промерзания.','sunny','frequent','Поставьте на открытом воздухе на солнце или в лёгкую полутень.','В сезон роста поливайте после подсыхания поверхности грунта, не пересушивая маленький горшок; зимой защищайте корни от сильного промерзания.'),
  (78,'Бонсай Радермахера','Radermachera','Комнатный бонсай из радермахеры с мелкими блестящими листочками.','Радермахера — вечнозелёное дерево, которое в помещении ценят за густую перистую листву. Точный вид бонсай в названии не указан, поэтому оставляем определение на уровне рода.','Поставьте в яркий непрямой свет и тепло. Поливайте после подсыхания верхнего слоя грунта, не допуская длительной сырости; избегайте резкой перестановки и холодных сквозняков.','diffused','moderate','Поставьте в яркий непрямой свет и тепло.','Поливайте после подсыхания верхнего слоя грунта, не допуская длительной сырости; избегайте резкой перестановки и холодных сквозняков.'),
  (56,'Бонсай Гранат','Punica granatum','Бонсай из граната с мелкой листвой и сезонным листопадом.','Гранат — листопадный кустарник, который можно формировать как бонсай. При хорошем освещении взрослое растение способно цвести; наличие плодов у этого экземпляра не обещаем.','Поставьте в максимально светлое место с доступом к солнцу. В сезон роста поливайте после подсыхания верхнего слоя, не пересушивая маленький горшок; зимой в прохладе поливайте реже.','sunny','moderate','Поставьте в максимально светлое место с доступом к солнцу.','В сезон роста поливайте после подсыхания верхнего слоя, не пересушивая маленький горшок; зимой в прохладе поливайте реже.'),
  (74,'Бонсай Падуб (Илекс Крената)','Ilex crenata','Бонсай из падуба городчатого с мелкими блестящими листьями.','Ilex crenata — вечнозелёный японский падуб, который хорошо поддаётся формировке. Ягоды могут появиться только у женского растения после опыления; плодоношение не гарантируем.','Держите на открытом воздухе на солнце или в лёгкой полутени. Поливайте после лёгкого подсыхания поверхности и не допускайте ни пересушки маленького кома, ни застоя воды; зимой защищайте горшок от сильного промерзания.','sunny','moderate','Держите на открытом воздухе на солнце или в лёгкой полутени.','Поливайте после лёгкого подсыхания поверхности и не допускайте ни пересушки маленького кома, ни застоя воды; зимой защищайте горшок от сильного промерзания.'),
  (72,'Бонсай Олива Sylvestris','Olea europaea','Бонсай из оливы с узкими серебристо-зелёными листьями.','Олива — медленно растущее вечнозелёное дерево с плотными кожистыми листьями. В названии «Sylvestris» указана торговая форма; точный ботанический статус по этикетке не подтверждён.','Поставьте на самое светлое место с прямым солнцем. Поливайте после заметного подсыхания хорошо дренированного грунта; зимой держите светло и прохладнее, защищая небольшой горшок от мороза.','sunny','moderate','Поставьте на самое светлое место с прямым солнцем.','Поливайте после заметного подсыхания хорошо дренированного грунта; зимой держите светло и прохладнее, защищая небольшой горшок от мороза.'),
  (86,'Бонсай яблоня домашняя','Malus domestica','Бонсай из домашней яблони с сезонной листвой.','Домашняя яблоня — листопадное плодовое дерево. В форме бонсай её крону и корни поддерживают обрезкой; цветение и завязь плодов зависят от возраста, условий и опыления.','Держите на открытом воздухе в солнечном месте. В сезон роста поливайте регулярно после подсыхания поверхности грунта, не пересушивая маленький горшок; на зиму защищайте корни от сильного промерзания.','sunny','frequent','Держите на открытом воздухе в солнечном месте.','В сезон роста поливайте регулярно после подсыхания поверхности грунта, не пересушивая маленький горшок; на зиму защищайте корни от сильного промерзания.'),
  (143,'Мирсина африканская','Myrsine africana','Мирсина африканская — вечнозелёный куст с мелкими блестящими листьями.','Myrsine africana медленно растёт и хорошо переносит формирующую обрезку. Плоды появляются только при наличии мужского и женского растений, поэтому плодоношение одного экземпляра не обещаем.','Поставьте в светлое место с мягким солнцем или лёгкой полутенью. Поливайте после подсыхания поверхности грунта, не пересушивая весь ком; в холодный сезон защищайте контейнер от мороза.','sunny','moderate','Поставьте в светлое место с мягким солнцем или лёгкой полутенью.','Поливайте после подсыхания поверхности грунта, не пересушивая весь ком; в холодный сезон защищайте контейнер от мороза.'),
  (144,'Мирсина на штамбе','Myrsine','Штамбовая мирсина с мелкой плотной вечнозелёной листвой.','Штамбовая форма получается обрезкой и не обозначает отдельный вид. Точный вид этого экземпляра не подтверждён, поэтому оставляем определение на уровне рода Myrsine.','Поставьте в светлое место с мягким солнцем или лёгкой полутенью. Поливайте после подсыхания поверхности грунта, не пересушивая весь ком; зимой берегите небольшой горшок от мороза.','sunny','moderate','Поставьте в светлое место с мягким солнцем или лёгкой полутенью.','Поливайте после подсыхания поверхности грунта, не пересушивая весь ком; зимой берегите небольшой горшок от мороза.'),
  (191,'Туя Брабант','Thuja occidentalis ''Brabant''','Туя Брабант — уличное хвойное растение с плотной зелёной кроной.','Thuja occidentalis Brabant — быстрорастущий вечнозелёный сорт с чешуйчатой хвоей. В грунте его часто используют для живых изгородей; в контейнере корни требуют большей защиты зимой.','Высаживайте на открытом воздухе на солнце или в полутени. Поливайте после подсыхания поверхности грунта, не допуская длительной пересушки контейнера; обеспечьте дренаж и защитите горшок от сильного промерзания.','sunny','moderate','Высаживайте на открытом воздухе на солнце или в полутени.','Поливайте после подсыхания поверхности грунта, не допуская длительной пересушки контейнера; обеспечьте дренаж и защитите горшок от сильного промерзания.'),
  (194,'Фикус Алтиссима','Ficus altissima','Фикус альтиссима с крупными плотными глянцевыми листьями.','Ficus altissima — тропическое вечнозелёное дерево, которое в комнате выращивают как крупное декоративнолистное растение. Окраска листьев зависит от формы и освещения.','Поставьте в яркий рассеянный свет и стабильное тепло. Поливайте после подсыхания верхнего слоя грунта, сливая воду из поддона; берегите от холодного сквозняка.','diffused','moderate','Поставьте в яркий рассеянный свет и стабильное тепло.','Поливайте после подсыхания верхнего слоя грунта, сливая воду из поддона; берегите от холодного сквозняка.');
